package com.naimat.autotimelinesync;
import android.content.*;import android.net.Uri;import android.database.Cursor;import android.provider.*;import android.graphics.*;import android.media.*;import android.util.LruCache;import org.json.*;import java.io.*;import java.util.*;

public final class MediaFiles {
 public final Context context;public final LinkedHashMap<String,Uri> images=new LinkedHashMap<>();
 private final LruCache<String,Bitmap> cache=new LruCache<String,Bitmap>(48*1024*1024){protected int sizeOf(String k,Bitmap b){return b.getAllocationByteCount();}};
 public MediaFiles(Context c){context=c.getApplicationContext();}
 public InputStream open(Uri uri)throws IOException{InputStream s=context.getContentResolver().openInputStream(uri);if(s==null)throw new IOException("Cannot open "+uri);return s;}
 public String text(Uri uri)throws IOException{try(InputStream s=open(uri);ByteArrayOutputStream b=new ByteArrayOutputStream()){byte[]buf=new byte[32768];int n;while((n=s.read(buf))!=-1){b.write(buf,0,n);if(b.size()>50*1024*1024)throw new IOException("JSON exceeds 50 MiB.");}return b.toString("UTF-8");}}
 public String name(Uri u){if("file".equals(u.getScheme()))return new File(u.getPath()).getName();try(Cursor c=context.getContentResolver().query(u,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())return c.getString(0);}catch(Exception ignored){}return u.getLastPathSegment();}
 public double duration(Uri uri)throws Exception{MediaMetadataRetriever m=new MediaMetadataRetriever();try{m.setDataSource(context,uri);String value=m.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION);if(value==null)throw new IOException("Audio duration could not be read.");return Double.parseDouble(value)/1000;}finally{m.release();}}
 public void retain(Intent data){if(data==null||data.getData()==null)return;try{context.getContentResolver().takePersistableUriPermission(data.getData(),data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));}catch(SecurityException ignored){}}
 public void folder(Uri tree)throws Exception{images.clear();cache.evictAll();if("file".equals(tree.getScheme())){File[]fs=new File(tree.getPath()).listFiles();if(fs!=null)for(File f:fs)if(f.isFile())add(f.getName(),Uri.fromFile(f));return;}Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));try(Cursor c=context.getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME},null,null,null)){if(c==null)throw new IOException("Folder is not readable.");while(c.moveToNext())add(c.getString(1),DocumentsContract.buildDocumentUriUsingTree(tree,c.getString(0)));}if(images.isEmpty())throw new IOException("No numbered PNG, JPG, JPEG or WebP images in this folder.");}
 public void add(String name,Uri uri)throws Exception{if(name==null||!name.matches("(?i)[0-9]{3,}\\.(png|jpe?g|webp)"))return;String id=name.substring(0,name.lastIndexOf('.'));if(images.containsKey(id))throw new IOException("Duplicate image ID "+id+". Keep one file per scene ID.");images.put(id,uri);}
 public void validate(ATSModel m,Uri narration)throws Exception{if(narration==null)throw new Exception("Narration audio is required.");double actual=duration(narration);if(Math.abs(actual-m.duration)>1.0/m.fps)throw new Exception("$.audio_duration: package "+m.duration+"s differs from narration "+actual+"s. Use the exact uploaded audio duration.");for(ATSModel.Scene s:m.scenes){if(!images.containsKey(s.id))throw new Exception("$.scenes["+(Integer.parseInt(s.id)-1)+"].image_id: missing image "+s.id+" in the selected folder.");BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;try(InputStream stream=open(images.get(s.id))){BitmapFactory.decodeStream(stream,null,o);}if(o.outWidth<1||o.outHeight<1)throw new Exception("Image "+s.id+" is not a readable image.");}if(images.size()!=m.scenes.size())m.notices.add("Selected folder has "+(images.size()-m.scenes.size())+" unused images.");}
 public synchronized Bitmap image(String id,int maximum)throws Exception{String key=id+":"+maximum;Bitmap b=cache.get(key);if(b!=null)return b;Uri u=images.get(id);if(u==null)throw new IOException("Missing image "+id);BitmapFactory.Options opt=new BitmapFactory.Options();opt.inJustDecodeBounds=true;try(InputStream s=open(u)){BitmapFactory.decodeStream(s,null,opt);}int sample=1;while(Math.max(opt.outWidth,opt.outHeight)/sample>maximum*1.5)sample*=2;opt.inJustDecodeBounds=false;opt.inSampleSize=sample;opt.inPreferredConfig=Bitmap.Config.ARGB_8888;try(InputStream s=open(u)){b=BitmapFactory.decodeStream(s,null,opt);}if(b==null)throw new IOException("Cannot decode "+id);try(InputStream s=open(u)){int orientation=new ExifInterface(s).getAttributeInt(ExifInterface.TAG_ORIENTATION,1);Matrix mat=new Matrix();switch(orientation){case 2:mat.setScale(-1,1);break;case 3:mat.setRotate(180);break;case 4:mat.setScale(1,-1);break;case 5:mat.setRotate(90);mat.postScale(-1,1);break;case 6:mat.setRotate(90);break;case 7:mat.setRotate(270);mat.postScale(-1,1);break;case 8:mat.setRotate(270);}if(!mat.isIdentity())b=Bitmap.createBitmap(b,0,0,b.getWidth(),b.getHeight(),mat,true);}catch(IOException ignored){}cache.put(key,b);return b;}
 public void clear(){cache.evictAll();}
 public static void clean(File folder,File parent)throws IOException{String p=parent.getCanonicalPath()+File.separator;if(!folder.getCanonicalPath().startsWith(p))throw new IOException("Cleanup outside private task directory blocked.");File[]files=folder.listFiles();if(files!=null)for(File f:files){if(f.isDirectory())clean(f,parent);else if(!f.delete())throw new IOException("Could not remove temporary "+f.getName());}if(!folder.delete()&&folder.exists())throw new IOException("Could not remove task folder.");}
}
